create table if not exists public.activity_events (id bigint generated always as identity primary key, visitor_id text not null, event_name text not null, test_number integer, question_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists activity_events_created_idx on public.activity_events(created_at desc);
create index if not exists activity_events_visitor_idx on public.activity_events(visitor_id);
alter table public.activity_events enable row level security;
revoke all on public.activity_events from anon, authenticated;
grant all on public.activity_events to service_role;
create or replace function public.admin_dashboard_stats() returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('visitors_30d',(select count(distinct visitor_id) from activity_events where created_at>=now()-interval '30 days'),'visitors_all_time',(select count(distinct visitor_id) from activity_events),'page_views_30d',(select count(*) from activity_events where event_name='page_view' and created_at>=now()-interval '30 days'),'questions_viewed_30d',(select count(*) from activity_events where event_name='question_viewed' and created_at>=now()-interval '30 days'),'questions_answered_30d',(select count(*) from activity_events where event_name='question_answered' and created_at>=now()-interval '30 days'),'tests_started_30d',(select count(*) from activity_events where event_name in ('test_started','retake_started') and created_at>=now()-interval '30 days'),'tests_completed_30d',(select count(*) from activity_events where event_name='test_completed' and created_at>=now()-interval '30 days'),'popular_questions',coalesce((select jsonb_agg(jsonb_build_object('question_id',question_id,'attempts',attempts) order by attempts desc) from (select question_id,count(*) attempts from activity_events where event_name='question_answered' and question_id is not null and created_at>=now()-interval '30 days' group by question_id order by count(*) desc limit 10) p),'[]'::jsonb)); $$;
revoke all on function public.admin_dashboard_stats() from public, anon, authenticated;
grant execute on function public.admin_dashboard_stats() to service_role;
